 
-- Скрипт 3. Загрузка данных ресурсов в OLAP-базу (PostgreSQL, база dataparts)
-- Строки insert из скрипта 2 (столбец [sql]) вставляются на место отметок.
-- DO-блок: каждый ресурс во вложенном блоке (очистка + вставка), ошибка
-- откатывает только его. Можно запускать повторно.
 

DO $data$
BEGIN

    -- Единицы измерения (ресурс «Единица измерения»)
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_ranges;

        -- строки из генератора (скрипт 2)
        

        RAISE NOTICE 'dim_ranges: загружено строк %', (SELECT count(*) FROM dim_ranges);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_ranges: ошибка %', SQLERRM;
    END;

    -- Категории товаров (иерархия)
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_categories;

            
        

        RAISE NOTICE 'dim_categories: загружено строк %', (SELECT count(*) FROM dim_categories);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_categories: ошибка %', SQLERRM;
    END;

    -- Номенклатура (ресурс «Товар»)
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_products;

        

        RAISE NOTICE 'dim_products: загружено строк %', (SELECT count(*) FROM dim_products);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_products: ошибка %', SQLERRM;
    END;

    -- Группы поставщиков
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_vendor_groups;

        

        RAISE NOTICE 'dim_vendor_groups: загружено строк %', (SELECT count(*) FROM dim_vendor_groups);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_vendor_groups: ошибка %', SQLERRM;
    END;

    -- Поставщики (ресурс «Поставщик»)
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_vendors;

        

        RAISE NOTICE 'dim_vendors: загружено строк %', (SELECT count(*) FROM dim_vendors);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_vendors: ошибка %', SQLERRM;
    END;

    -- Клиенты (ресурс «Клиент»)
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_clients;

        

        RAISE NOTICE 'dim_clients: загружено строк %', (SELECT count(*) FROM dim_clients);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_clients: ошибка %', SQLERRM;
    END;

    -- Сотрудники (ресурс «Сотрудник»)
    BEGIN
        -- очистка, чтобы загрузку можно было повторять
        DELETE FROM dim_personnel;

        -- строки из генератора (скрипт 2)
        

        RAISE NOTICE 'dim_personnel: загружено строк %', (SELECT count(*) FROM dim_personnel);
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dim_personnel: ошибка %', SQLERRM;
    END;

END
$data$;

-- Проверка: количество строк по ресурсам
SELECT 'dim_ranges' AS resource, count(*) AS cnt FROM dim_ranges
UNION ALL
SELECT 'dim_categories' AS resource, count(*) AS cnt FROM dim_categories
UNION ALL
SELECT 'dim_products' AS resource, count(*) AS cnt FROM dim_products
UNION ALL
SELECT 'dim_vendor_groups' AS resource, count(*) AS cnt FROM dim_vendor_groups
UNION ALL
SELECT 'dim_vendors' AS resource, count(*) AS cnt FROM dim_vendors
UNION ALL
SELECT 'dim_clients' AS resource, count(*) AS cnt FROM dim_clients
UNION ALL
SELECT 'dim_personnel' AS resource, count(*) AS cnt FROM dim_personnel
ORDER BY resource;

-- Группы поставщиков с числом поставщиков (как на паре)
SELECT g.external_id AS id, g.name, count(v.id) AS vendors_cnt
FROM dim_vendor_groups g
LEFT JOIN dim_vendors v ON v.group_external_id = g.external_id
GROUP BY g.external_id, g.name
ORDER BY g.name;
